"""Finite Native controller requests for stop, stand and park probes.

These timing profiles distinguish software trajectories. They do not define
the statutory words or prove the operator's observed activity.
"""
from __future__ import annotations

from branch_context import ACTIVITIES
from geometry import FRAME_COUNT


def command(activity: str, frame: int) -> dict:
    if activity not in ACTIVITIES or not isinstance(frame, int) or not 0 <= frame < FRAME_COUNT:
        raise ValueError("Unknown activity or Native frame")
    if activity == "stop":
        phase = "approach" if frame < 60 else "halt" if frame < 140 else "departure"
    elif activity == "stand":
        phase = "approach" if frame < 60 else "standing_request" if frame < 440 else "departure"
    else:
        phase = "approach" if frame < 60 else "parking_request"
    if phase == "approach":
        return {"phase": phase, "throttle": .12, "brake": 0.0, "hand_brake": False}
    if phase == "departure":
        return {"phase": phase, "throttle": .18, "brake": 0.0, "hand_brake": False}
    return {"phase": phase, "throttle": 0.0, "brake": 1.0,
            "hand_brake": phase == "parking_request"}


def apply(vehicle, control_type, activity: str, frame: int) -> dict:
    """Exercise a CARLA-shaped apply_control call without importing CARLA."""
    row = command(activity, frame)
    vehicle.apply_control(control_type(throttle=row["throttle"], brake=row["brake"],
                                       hand_brake=row["hand_brake"]))
    return row

"""Exact draft requests for the remaining 484B.450(1)(k) alternatives.

Requests are engineering constructions. Source records and Native readback must
establish what occurred; this module assigns no legal or physical outcome.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from branch_context import ACTIVITIES, EXCEPTIONS, checked_record, validate
from geometry import EXCAVATION, FRAME_COUNT, ROAD, largest_open_width

ASSIGNMENT = "training__C135702__NRS-484B-450-1k__motor_vehicle_driver"
POSITIONS = {"alongside": (7.5, 2.2), "opposite": (2.5, -2.2)}
KINDS = {"physical_obstruction", "excavation"}


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _inside(outer: tuple[float, ...], inner: tuple[float, ...]) -> bool:
    return outer[0] < inner[0] < inner[2] < outer[2] and outer[1] < inner[1] < inner[3] < outer[3]


def check_geometry(request: dict) -> dict:
    """Check the authored spatial alternative and preserve readback uncertainty."""
    placement = request.get("placement_request")
    kind = request.get("obstruction_kind_request")
    if placement not in POSITIONS or kind not in KINDS:
        raise ValueError("Unknown statutory placement or obstruction kind")
    center = POSITIONS[placement]
    park_body = (center[0] - 2.4, center[1] - .9, center[0] + 2.4, center[1] + .9)
    if not _inside(ROAD, park_body) or not _inside(ROAD, EXCAVATION):
        raise ValueError("Authored body or obstruction misses surveyed highway")
    same_side = (center[1] > 0) == ((EXCAVATION[1] + EXCAVATION[3]) / 2 > 0)
    if same_side != (placement == "alongside"):
        raise ValueError("Authored alongside/opposite placement differs")
    if placement == "opposite":
        if not (park_body[0] < EXCAVATION[2] and EXCAVATION[0] < park_body[2]):
            raise ValueError("Opposite parked body misses obstruction station")
    elif not (0 < park_body[0] - EXCAVATION[2] <= .5):
        raise ValueError("Alongside parked body overlaps or is remote from obstruction")
    return {"placement_request": placement, "obstruction_kind_request": kind,
            "park_center_xy_m": list(center), "park_body_xy_m": list(park_body),
            "obstruction_xy_m": list(EXCAVATION), "road_xy_m": list(ROAD),
            "authored_open_width_m": largest_open_width(ROAD, [EXCAVATION, park_body]),
            "native_readback_observed": False, "excavation_observed": False,
            "traffic_obstruction_judged": None}


def check_request(config_path: Path, context_path: Path) -> dict:
    """Gate a draft branch against separately hashed reviewed original records."""
    request = json.loads(config_path.read_text())
    case_id = request.get("case_id", "")
    if not case_id.startswith(ASSIGNMENT + "__selected_statutory_"):
        raise ValueError("Exact statutory draft case identity required")
    if (request.get("law_id"), request.get("cell_id"), request.get("actor")) != (
        "NRS-484B-450-1k", "C135702", "motor_vehicle_driver"
    ):
        raise ValueError("Frozen statutory assignment identity differs")
    if (request.get("rate_hz"), request.get("duration_s"), request.get("frames")) != (20, 30, FRAME_COUNT):
        raise ValueError("Exact camera and duration plan differs")
    if request.get("camera_names") != ["overview", "approach", "reference_corner", "driver_reference"]:
        raise ValueError("Four original camera sources required")
    if request.get("physical_acceptance_claimed") is not False or request.get("legal_verdict_claimed") is not False:
        raise ValueError("Draft asserts an unobserved outcome")
    activity, exception = request.get("activity_request"), request.get("exception_request")
    if activity not in ACTIVITIES or exception not in EXCEPTIONS | {None}:
        raise ValueError("Unknown activity or exception request")
    geometry = check_geometry(request)
    gate = validate(context_path.parent, context_path, case_id, activity, exception)
    context = json.loads(context_path.read_text())
    if context.get("activity_request") != activity or context.get("exception_request") != exception:
        raise ValueError("Original branch context request differs")
    spatial = context.get("spatial_source", {})
    if set(spatial) != {"placement", "obstruction_kind"}:
        raise ValueError("Separate placement and obstruction source gates required")
    for name, expected in (("placement", geometry["placement_request"]),
                           ("obstruction_kind", geometry["obstruction_kind_request"])):
        record = checked_record(context_path.parent, spatial[name], name)
        if record.get("requested_value") != expected or not record.get("scene_scope"):
            raise ValueError("Original spatial source differs from request: " + name)
        if name == "obstruction_kind" and expected == "excavation" and not record.get("excavation_source_refs"):
            raise ValueError("Excavation request lacks original excavation source")
    return {"format": "c135702-statutory-draft-gate", "case_id": case_id,
            "config_sha256": _sha(config_path), "context_sha256": _sha(context_path),
            "source_gate_sha256": gate["source_sha256"],
            "spatial_sources": {name: spatial[name]["sha256"] for name in sorted(spatial)},
            "authored_geometry": geometry, "physical_acceptance_claimed": False,
            "legal_acceptance_claimed": False}

"""Source gates for proposed activity and exception comparison variants.

An authored branch request is a controller target. It never proves an activity,
exception, physical obstruction, or legal consequence. A later Native capture
must copy the independently reviewed original records and retain their hashes.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

ACTIVITIES = {"stop", "stand", "park"}
EXCEPTIONS = {"traffic_conflict", "law_direction", "police_direction", "traffic_device"}


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def checked_record(root: Path, item: dict, expected_kind: str) -> dict:
    if item.get("kind") != expected_kind or item.get("provenance") != "reviewed_original_source":
        raise ValueError("Original reviewed source kind required: " + expected_kind)
    relative = Path(item.get("path", ""))
    if relative.is_absolute() or not relative.parts or ".." in relative.parts:
        raise ValueError("Unsafe reviewed source path")
    source = (root / relative).resolve()
    if root.resolve() not in source.parents or not source.is_file() or sha(source) != item.get("sha256"):
        raise ValueError("Reviewed original source missing or changed")
    payload = json.loads(source.read_text())
    if payload.get("source_kind") != expected_kind or not payload.get("original_record_id"):
        raise ValueError("Reviewed original source lacks exact identity")
    return payload


def validate(root: Path, context_path: Path, case_id: str, activity: str,
             exception_request: str | None) -> dict:
    """Validate source links; retain all event and applicability judgments open."""
    if activity not in ACTIVITIES or exception_request not in EXCEPTIONS | {None}:
        raise ValueError("Unknown statutory branch request")
    context = json.loads(context_path.read_text())
    if context.get("case_id") != case_id or context.get("source_kind") != "reviewed_branch_context":
        raise ValueError("Exact case-specific original branch context required")
    activity_source = checked_record(root, context.get("activity_source", {}), "operator_activity")
    if activity_source.get("requested_activity") != activity:
        raise ValueError("Operator activity source does not match branch request")
    authority = context.get("exception_sources", {})
    if set(authority) != EXCEPTIONS:
        raise ValueError("Four separate exception source gates required")
    inspected = {name: checked_record(root, authority[name], name) for name in sorted(EXCEPTIONS)}
    for name, record in inspected.items():
        if record.get("requested_exception") not in (None, name):
            raise ValueError("Exception source mixes statutory branches")
    if exception_request is not None:
        selected = inspected[exception_request]
        if selected.get("requested_exception") != exception_request:
            raise ValueError("Selected exception lacks source-bound request")
        if not selected.get("event_window") or not selected.get("scene_scope"):
            raise ValueError("Selected exception lacks original time or place scope")
        if exception_request in {"police_direction", "traffic_device"} and not selected.get("original_instruction"):
            raise ValueError("Direction branch lacks original instruction")
        if exception_request == "law_direction" and not selected.get("law_citation"):
            raise ValueError("Law exception branch lacks cited legal authority")
        if exception_request == "traffic_conflict" and not selected.get("traffic_source_refs"):
            raise ValueError("Traffic necessity branch lacks original traffic sources")
    return {"format": "c135702-branch-source-gate", "case_id": case_id,
            "activity_request": activity, "exception_request": exception_request,
            "context_sha256": sha(context_path),
            "source_sha256": {"activity": context["activity_source"]["sha256"],
                              **{name: authority[name]["sha256"] for name in sorted(EXCEPTIONS)}},
            "physical_acceptance_claimed": False, "legal_acceptance_claimed": False,
            "activity_observed": False, "exception_applies": None}

"""Join original obstruction samples to four camera and video frame identities."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
FRAMES = 600


def _rows(path: Path) -> list[dict]:
    if not path.is_file():
        raise ValueError("Missing required original source: " + path.name)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def check(root: Path, source_kind: str = "original_native") -> dict:
    root = Path(root)
    names = ("native_samples.jsonl", "video_frames.jsonl", "camera-frames.jsonl")
    samples, frame_map, cameras = (_rows(root / name) for name in names)
    if len(samples) != FRAMES or len(frame_map) != FRAMES or len(cameras) != FRAMES * len(VIEWS):
        raise ValueError("Incomplete 600-frame four-camera source")
    camera_lookup = {(row.get("frame"), row.get("camera")): row for row in cameras}
    if len(camera_lookup) != len(cameras):
        raise ValueError("Duplicate original camera identity")
    for index, (sample, mapping) in enumerate(zip(samples, frame_map)):
        native = sample.get("native_frame")
        if type(native) is not int or native < 0 or mapping.get("native_frame") != native:
            raise ValueError("Original Native frame join differs")
        if mapping.get("video_frame") != index or abs(float(sample.get("time_s", -1)) - index / 20) > 1e-7 or abs(float(mapping.get("time_s", -1)) - index / 20) > 1e-7:
            raise ValueError("Original time/video frame join differs")
        if source_kind == "original_native" and sample.get("source_kind") != "original_native":
            raise ValueError("Original Native sample provenance missing")
        camera_map = mapping.get("camera_native_frames")
        if camera_map != {name: native for name in VIEWS}:
            raise ValueError("Original camera frame map differs")
        for view in VIEWS:
            row = camera_lookup.get((index, view))
            if row is None or row.get("native_frame") != native:
                raise ValueError("Missing original camera source join")
            digest = row.get("rgb_sha256")
            if not isinstance(digest, str) or len(digest) != 64 or any(ch not in "0123456789abcdef" for ch in digest):
                raise ValueError("Original camera pixel digest absent")
            if source_kind == "original_native" and row.get("source_kind") != "original_native":
                raise ValueError("Original camera provenance missing")
    return {"passed": True, "frames": FRAMES, "camera_frames": len(cameras),
            "source_kind": source_kind, "source_sha256": {name: _sha(root / name) for name in names},
            "original_pixels_decoded": False, "physical_cause_confirmed": False,
            "legal_verdict_claimed": False}
